int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int M, N;
    cin >> M >> N;

    vector<vector<int>> estoque(M + 1, vector<int>(N + 1, 0));

    for (int i = 1; i <= M; i++) {
        for (int j = 1; j <= N; j++) {
            cin >> estoque[i][j];
        }
    }

    int P;
    cin >> P;

    int vendidas = 0;

    for (int k = 0; k < P; k++) {
